local config = {
  ui_story_5030_50300001_1_dialog_content = "Just look at this glinting, metallic sheen...",
  ui_story_5030_50300001_2_dialog_content = "And this gorgeous, streamlined body! It's the very pinnacle of cutting-edge technology!",
  ui_story_5030_50300001_3_dialog_content = "Oh, and check out all of these rusted spots! Aren't they just to die for?",
  ui_story_5030_50300001_4_dialog_content = "They don't take away from its charm at all! If anything, they give it an air of mystery...",
  ui_story_5030_50300001_5_dialog_content = "In any case, all of these characteristics, endearing as they may be, are the most trivial aspects of the Sorcery Pot!",
  ui_story_5030_50300001_6_dialog_content = "What makes it truly irresistible to all...",
  ui_story_5030_50300001_7_dialog_content = "What makes it so valuable that everyone has come here today for a chance to obtain it...",
  ui_story_5030_50300001_8_dialog_content = "Is the fact that this pot, which was found deep within the ruins of ages past... was used by none other than Uncle Johnny himself!",
  ui_story_5030_50300001_9_dialog_content = "Uncle Johnny? You mean THE Uncle Johnny?!",
  ui_story_5030_50300001_10_dialog_content = "Did it really belong to Uncle Johnny?",
  ui_story_5030_50300001_11_dialog_content = "I heard he used this very pot to come up with all of his legendary dishes!",
  ui_story_5030_50300001_12_dialog_content = "They say you don't have to add any seasonings when you cook with it. Apparently, it automatically adjusts the flavor of whatever you're making...",
  ui_story_5030_50300001_13_dialog_content = "Could a miraculous pot like that actually exist?!",
  ui_story_5030_50300001_14_dialog_content = "I... I gotta have it! Let me try my luck!",
  ui_story_5030_50300001_15_dialog_content = "Er, pardon me, Miss...",
  ui_story_5030_50300001_16_dialog_content = "Do I just have to sign up with you to get started?",
  ui_story_5030_50300001_17_dialog_content = "That's right! Just register with me, everyone's chosen host: Rainbow!",
  ui_story_5030_50300001_18_dialog_content = "Oh, and no need to be so polite. Just call me by my name!",
  ui_story_5030_50300001_19_dialog_content = "Now then, if you wanna sign up for the contest, just give me your name and a reason for joining!",
  ui_story_5030_50300001_20_dialog_content = "Oh, I almost forgot!",
  ui_story_5030_50300001_21_dialog_content = "You'll need to tell us what food you're planning to sell at the fair as well!",
  ui_story_5030_50300001_22_dialog_content = "Ah, alright then.",
  ui_story_5030_50300001_23_dialog_content = "Name: Fleur.",
  ui_story_5030_50300001_24_dialog_content = "Reason for participating: to hone my cooking skills.",
  ui_story_5030_50300001_25_dialog_content = "Also... I'd like to find out what bread made from this kind of cookware tastes like.",
  ui_story_5030_50300001_26_dialog_content = "What I plan to sell: bread.",
  ui_story_5030_50300001_27_dialog_content = "Oh! Me! I wanna sign up, too! Over here!",
  ui_story_5030_50300001_28_dialog_content = "Oi, oi! No pushing! I understand you're all excited to take part, but—",
  ui_story_5030_50300001_29_dialog_content = "Pardon me, Ms. Rainbow, but what exactly are the conditions for winning?",
  ui_story_5030_50300001_30_dialog_content = "Oops! I almost forgot that, too!",
  ui_story_5030_50300001_31_dialog_content = "Thanks for reminding me, handsome!",
  ui_story_5030_50300001_32_dialog_content = "Quiet down, everyone! Quiet down!",
  ui_story_5030_50300001_33_dialog_content = "Allow me to explain the winning condition for this contest before you sign up, because it's not too late to rethink your decision!",
  ui_story_5030_50300001_34_dialog_content = "So how do we win?",
  ui_story_5030_50300001_35_dialog_content = "Hmm?! Sir, where'd you come from?",
  ui_story_5030_50300001_36_dialog_content = "Wait! First let me give you this registration form... H-Hang on! Settle down, everyone! There are plenty of sheets to go around!",
  ui_story_5030_50300001_37_dialog_content = "Whew... There are so many of you, even I'm having a hard time keeping up!",
  ui_story_5030_50300001_38_dialog_content = "Let me see...",
  ui_story_5030_50300001_39_dialog_content = "The winning condition is... to prioritize sales over profits!",
  ui_story_5030_50300001_40_dialog_content = "That means, whatever food a contestant chooses to sell...",
  ui_story_5030_50300001_41_dialog_content = "The more of it they sell, the greater their chances of winning!",
  ui_story_5030_50300001_42_dialog_content = "Oh, I see.",
  ui_story_5030_50300001_43_dialog_content = "Looks like I'll have to adjust the price of my shaved ice and go with a high volume low margin strategy.",
  ui_story_5030_50300001_44_dialog_content = "Though the contest itself isn't my primary objective...",
  ui_story_5030_50300001_45_dialog_content = "I'm still curious to see what kinds of foods the rest of the competition will be offering.",
  ui_story_5030_50300001_46_dialog_content = "After all, who doesn't get excited about new business prospects?",
  ui_story_5030_50300001_47_dialog_content = "Uh, sir...? Are you done filling out your form yet?",
  ui_story_5030_50300001_48_dialog_content = "But of course. Here you are, Miss.",
  ui_story_5030_50300001_49_dialog_content = "See you at the competition then, sir!",
  ui_story_5030_50300001_50_dialog_content = "Anyone else?",
  ui_story_5030_50300001_51_dialog_content = "Me.",
  ui_story_5030_50300001_52_dialog_content = "Wow! What a pleasure to meet such a spirited young lady!",
  ui_story_5030_50300001_53_dialog_content = "Though I gotta admit, you don't really look like the type that's good at cooking...",
  ui_story_5030_50300001_54_dialog_content = "Let's just take a quick peek at your registration form...",
  ui_story_5030_50300001_55_dialog_content = "Smokey, eh? And you'll be offering grilled meat? I see...",
  ui_story_5030_50300001_56_dialog_content = "W-Wait... You're only doing this to see if hand-grilled meat tastes better than meat that's been cooked using the Sorcery Pot?!",
  ui_story_5030_50300001_57_dialog_content = "Is there a rule against that?",
  ui_story_5030_50300001_58_dialog_content = "N-Not at all! Ahahaha...",
  ui_story_5030_50300001_59_dialog_content = "I was just a little surprised, is all!",
  ui_story_5030_50300001_60_dialog_content = "Hmm? Say, aren't you...?",
  ui_story_5030_50300001_61_dialog_content = "That's right! I'd like to sign up, too!",
  ui_story_5030_50300001_62_dialog_content = "See? My form's already filled out and everything!",
  ui_story_5030_50300001_63_dialog_content = "(Perfect! I bet I sounded super confident just now!)",
  ui_story_5030_50300001_64_dialog_content = "(Come on, PlayerName! Think about the secret cookbook that Anzu and Momo gave you!)",
  ui_story_5030_50300001_65_dialog_content = "(If I manage to win that legendary, fully-automatic pot...)",
  ui_story_5030_50300001_66_dialog_content = "(I can give it to Vice, and all of our lives will be so much better!)",
  ui_story_5030_50300001_67_dialog_content = "(It'll make things a lot more convenient in Cloud Gardens and on the Colossus, too!)",
  ui_story_5030_50300001_68_dialog_content = "Alrighty then, hand it over!",
  ui_story_5030_50300001_69_dialog_content = "Let's see... So your name is PlayerName, you'll be selling noodles, and your reason for participating is...",
  ui_story_5030_50300001_70_dialog_content = "Is that you want to \"fill everyone's bellies\"?!",
  ui_story_5030_50300001_71_dialog_content = "*Sobbing* What a touching and selfless reason...",
  ui_story_5030_50300001_72_dialog_content = "PlayerName! I am honored to accept your registration form!",
  ui_story_5030_50300001_73_dialog_content = "I expect great things from you, so do your best!",
  ui_story_5030_50300001_74_dialog_content = "Ha... Haha...",
  ui_story_5030_50300001_75_dialog_content = "I did go a little overboard on my application, but I guess... okay?",
  ui_story_5030_50300001_76_dialog_content = "Alright, everyone! The registration period has come to a close!",
  ui_story_5030_50300001_77_dialog_content = "All contestants, please report to your designated stalls to prepare your ingredients and utensils!",
  ui_story_5030_50300001_78_dialog_content = "The contest will officially begin in thirty minutes!",
  ui_story_5030_50300001_79_dialog_content = "As for how you'll draw more customers to your stalls...",
  ui_story_5030_50300001_80_dialog_content = "Well, that's not for me to tell you! You'll have to use your wits and your wares to answer that question for yourself!",
  ui_story_5030_50300001_81_dialog_content = "And with that, let the countdown... begin!",
  ui_story_5030_50300001_82_dialog_content = "Whew! Now for one last check...",
  ui_story_5030_50300001_83_dialog_content = "The noodle bowls, the broth, and the toppings are all portioned out and ready to go...",
  ui_story_5030_50300001_84_dialog_content = "I can't afford to get distracted!",
  ui_story_5030_50300001_85_dialog_content = "Remember, PlayerName! Everyone in Cloud Gardens and on the Colossus is counting on you!",
  ui_story_5030_50300001_86_dialog_content = "Deep breaths, deep breaths... Ha... Alright, I feel calm and collected...",
  ui_story_5030_50300001_87_dialog_content = "Now then...",
  ui_story_5030_50300001_88_dialog_content = "<size=45>Let's get the show on the road!!!</size>",
  ui_story_5030_50300002_1_dialog_content = "Another!",
  ui_story_5030_50300002_2_dialog_content = "Going a little fast there, aren't ya, Jona?",
  ui_story_5030_50300002_3_dialog_content = "\"Live life to the fullest,\" isn't that what we say?",
  ui_story_5030_50300002_4_dialog_content = "Drinking's all about having fun!",
  ui_story_5030_50300002_5_dialog_content = "What's the point of there being so many different kinds of liquor in the world then?",
  ui_story_5030_50300002_6_dialog_content = "If everyone drank like you, there would be no reason to experiment and make new drinks. Where's the fun in that?",
  ui_story_5030_50300002_7_dialog_content = "Bah! That's why I hate those weak cocktails.",
  ui_story_5030_50300002_8_dialog_content = "You ever considered the fact that others drink for not-so-pure reasons?",
  ui_story_5030_50300002_9_dialog_content = "All I'm saying is that I don't see the point of getting drunk so quickly.",
  ui_story_5030_50300002_10_dialog_content = "I think properly savoring the atmosphere is the best way to go about it.",
  ui_story_5030_50300002_11_dialog_content = "Isn't that right, PlayerName?",
  ui_story_5030_50300002_12_dialog_content = "It's been a while, hasn't it?",
  ui_story_5030_50300002_13_dialog_content = "Tell me... Have you been thinking of me at all lately?",
  ui_story_5030_50300002_14_dialog_content = "S-Sure I have!",
  ui_story_5030_50300002_15_dialog_content = "Oh?",
  ui_story_5030_50300002_16_dialog_content = "I see Vice and Carleen aren't around today. No wonder you agreed so quickly!",
  ui_story_5030_50300002_17_dialog_content = "Th-That's not it!!",
  ui_story_5030_50300002_18_dialog_content = "Sigh... I must admit, I'm a little disappointed.",
  ui_story_5030_50300002_19_dialog_content = "Are you shy because Jona's here, sweetheart?",
  ui_story_5030_50300002_20_dialog_content = "If PlayerName blushes any harder, his head might explode.",
  ui_story_5030_50300002_21_dialog_content = "Well, I suppose I'll let you off the hook... this time.",
  ui_story_5030_50300002_22_dialog_content = "Anyway, I don't know about you two, but I'm starting to feel a little peckish...",
  ui_story_5030_50300002_23_dialog_content = "Wait, aren't you running a stall over here, PlayerName?",
  ui_story_5030_50300002_24_dialog_content = "Y-Yeah!",
  ui_story_5030_50300002_25_dialog_content = "Do you two want some noodles? I have a bunch of different flavors!",
  ui_story_5030_50300002_26_dialog_content = "Sure! Wouldn't hurt to offer your business a little patronage, after all!",
  ui_story_5030_50300002_27_dialog_content = "Give us two orders of noodles with meat sauce, yeah?",
  ui_story_5030_50300002_28_dialog_content = "No problem!",
  ui_story_5030_50300002_29_dialog_content = "Order's here!",
  ui_story_5030_50300002_30_dialog_content = "I'm excited to see what your cooking tastes like, PlayerName...",
  ui_story_5030_50300002_31_dialog_content = "Hmm. Not bad, I guess.",
  ui_story_5030_50300002_32_dialog_content = "Not bad at all!",
  ui_story_5030_50300002_33_dialog_content = "Hey, Azure... Don't you think...",
  ui_story_5030_50300002_34_dialog_content = "Doesn't this ramen taste like the ones from that shop?",
  ui_story_5030_50300002_35_dialog_content = "What?",
  ui_story_5030_50300002_36_dialog_content = "Ah... You mean the shop where we first met?",
  ui_story_5030_50300002_37_dialog_content = "Yes.",
  ui_story_5030_50300002_38_dialog_content = "When I saw you flirting with that young bartender at the time, I almost mistook you for some sort of alcoholic trying to swindle free drinks.",
  ui_story_5030_50300002_39_dialog_content = "For your information, you didn't seem so normal yourself with the well over 20 empty shot glasses sitting in front of you, and you kept hollering for more...",
  ui_story_5030_50300002_40_dialog_content = "I honestly thought you were just a drunken slob without an ounce of self-control.",
  ui_story_5030_50300002_41_dialog_content = "So how did the two of you end up becoming such good friends?",
  ui_story_5030_50300002_42_dialog_content = "\"Good friends\"?",
  ui_story_5030_50300002_43_dialog_content = "That sounds so childish, something only a teen would say.",
  ui_story_5030_50300002_44_dialog_content = "Now you're the one who needs to take it easy on our little Caelestite friend, Jona. We don't want to make him blush again!",
  ui_story_5030_50300002_45_dialog_content = "If you want to know how our relationship gradually grew into what it is today...",
  ui_story_5030_50300002_46_dialog_content = "If memory serves me right, I'd say it all started the day we decided to drive with our eyes closed together...",
  ui_story_5030_50300002_47_dialog_content = "Yeah, that sounds about right!",
  ui_story_5030_50300002_48_dialog_content = "By closing our eyes and focusing on our sense of touch as well as the point of contact between our hands and the steering wheel...",
  ui_story_5030_50300002_49_dialog_content = "We could feel a deeper connection between our bodies and our machines.",
  ui_story_5030_50300002_50_dialog_content = "It was thanks to that muscle memory that we were able to drive that behemoth of ours.",
  ui_story_5030_50300002_51_dialog_content = "Yeah... That was a blast!",
  ui_story_5030_50300002_52_dialog_content = "That sounds super dangerous!",
  ui_story_5030_50300002_53_dialog_content = "For us, danger and pleasure are two sides of the same coin.",
  ui_story_5030_50300002_54_dialog_content = "Now that you mention it, that time when we beat the hell out of those Eclipsites was pretty fun, too.",
  ui_story_5030_50300002_55_dialog_content = "At least that sounds a lot more normal than driving with your eyes closed...",
  ui_story_5030_50300002_56_dialog_content = "Oh, you mean the time when we agreed to fight using only a single hand?",
  ui_story_5030_50300002_57_dialog_content = "Forget I said anything.",
  ui_story_5030_50300002_58_dialog_content = "Yeah, that was a real good time.",
  ui_story_5030_50300002_59_dialog_content = "Sure, we got a little beat up for it, but the adrenaline rush was absolutely irresistible.",
  ui_story_5030_50300002_60_dialog_content = "I couldn't agree more. And the cold beer we had afterwards really rounded out the experience.",
  ui_story_5030_50300002_61_dialog_content = "So it's such a pity...",
  ui_story_5030_50300002_62_dialog_content = "A pity?",
  ui_story_5030_50300002_63_dialog_content = "Ah! I-I'm sorry, I don't really have any alcoholic drinks here.",
  ui_story_5030_50300002_64_dialog_content = "Hmm? No dear, I was going to say that it's a pity Jona here doesn't enjoy flirting with boys.",
  ui_story_5030_50300002_65_dialog_content = "H-How is that pitiful?",
  ui_story_5030_50300002_66_dialog_content = "Agreed.",
  ui_story_5030_50300002_67_dialog_content = "I don't care to pal around with ignorant teenagers... unlike you.",
  ui_story_5030_50300002_68_dialog_content = "Oh, my...",
  ui_story_5030_50300002_69_dialog_content = "My favorite thing is watching them blush as they try to keep their composure!",
  ui_story_5030_50300002_70_dialog_content = "You done yet? If you are, let's move along and find another place to drink.",
  ui_story_5030_50300002_71_dialog_content = "You're lucky I haven't finished this booze that I swiped earlier, or there'd be trouble right now.",
  ui_story_5030_50300002_72_dialog_content = "As blunt and uncivilized as ever, I see...",
  ui_story_5030_50300002_73_dialog_content = "Hey, that stall over there...",
  ui_story_5030_50300002_74_dialog_content = "Isn't that PlayerName's noodle stall?",
  ui_story_5030_50300002_75_dialog_content = "Those two ladies with him...",
  ui_story_5030_50300002_76_dialog_content = "Hmm? What's this? I sense the presence of a lovely lady nearby...",
  ui_story_5030_50300002_77_dialog_content = "I think it's Carleen.",
  ui_story_5030_50300002_78_dialog_content = "Carleen?",
  ui_story_5030_50300002_79_dialog_content = "Well, that's one lovely lady I don't care to provoke...",
  ui_story_5030_50300002_80_dialog_content = "Hmph, almost forgot this place was in Lumopolis' jurisdiction.",
  ui_story_5030_50300002_81_dialog_content = "Let's go, Azure!",
  ui_story_5030_50300002_82_dialog_content = "Wait, how many bottles did you steal from the City Lord's house earlier? Ugh, I really have no idea what to do with you sometimes...",
  ui_story_5030_50300002_83_dialog_content = "Better they end up being savored by me than letting them gather dust in some hoity-toity Lumopolis snob's cabinet.",
  ui_story_5030_50300002_84_dialog_content = "There's nothing I can do about her at this point, little Caelestite.",
  ui_story_5030_50300002_85_dialog_content = "The noodles were great. Take these ingredients as a thank you!",
  ui_story_5030_50300002_86_dialog_content = "Consider them a parting gift, since I couldn't find a chance to give them to you earlier. Till next we meet...",
  ui_story_5030_50300002_87_dialog_content = "Hmph... I'll be sure to remember which way those two went.",
  ui_story_5030_50300002_88_dialog_content = "Today's not the day to arrest them, so I'll leave them be for now.",
  ui_story_5030_50300002_89_dialog_content = "But she'd better not think I'll let her get away so easily next time!",
  ui_story_5030_50300002_90_dialog_content = "Just you wait and see, Jona...",
  ui_story_5030_50300003_1_dialog_content = "Merylt? Hello?",
  ui_story_5030_50300003_2_dialog_content = "Snap out of it and just go already!",
  ui_story_5030_50300003_3_dialog_content = "The Caelestite is right in front of you!",
  ui_story_5030_50300003_4_dialog_content = "I, I...",
  ui_story_5030_50300003_5_dialog_content = "I don't think anyone can hear you...",
  ui_story_5030_50300003_6_dialog_content = "There's no one around him right now, Merylt! This is a once-in-a-lifetime opportunity!",
  ui_story_5030_50300003_7_dialog_content = "I know, I know...",
  ui_story_5030_50300003_8_dialog_content = "Well, erm...",
  ui_story_5030_50300003_9_dialog_content = "PlayerName!",
  ui_story_5030_50300003_10_dialog_content = "Oh? Hey there, you three! What can I get you?",
  ui_story_5030_50300003_11_dialog_content = "Wait... You look awfully familiar...",
  ui_story_5030_50300003_12_dialog_content = "Yeah! We met once before on the deck, didn't we?",
  ui_story_5030_50300003_13_dialog_content = "Rainbow said you came to help with the circus. Is that right?",
  ui_story_5030_50300003_14_dialog_content = "Th-That's it! You're absolutely right!",
  ui_story_5030_50300003_15_dialog_content = "Hey, uh, just between us... Are you really after the Sorcery Pot?",
  ui_story_5030_50300003_16_dialog_content = "Heeheehee! Relax, would ya!",
  ui_story_5030_50300003_17_dialog_content = "We're here to help you secure that pot, don't you know?",
  ui_story_5030_50300003_18_dialog_content = "Help me?",
  ui_story_5030_50300003_19_dialog_content = "Wait a minute... Why would you suddenly offer to help?",
  ui_story_5030_50300003_20_dialog_content = "Also... How exactly are you planning on helping me, in the first place?",
  ui_story_5030_50300003_21_dialog_content = "You aren't planning on using me as one of the main ingredients in a broth or anything... Right?",
  ui_story_5030_50300003_22_dialog_content = "Of course not! What kind of monsters do you take us for?!",
  ui_story_5030_50300003_23_dialog_content = "Our plan is a lot more technical than that!",
  ui_story_5030_50300003_24_dialog_content = "Well, I can't say I don't have my doubts... But I guess it wouldn't hurt to hear you guys out...",
  ui_story_5030_50300003_25_dialog_content = "Haha! That's the spirit!",
  ui_story_5030_50300003_26_dialog_content = "I think it's time to share that story with our friend here, Merylt. Don't you agree?",
  ui_story_5030_50300003_27_dialog_content = "Uh... Story? What story?",
  ui_story_5030_50300003_28_dialog_content = "Just a little context, so that you fully appreciate the lengths we've gone to help you out, is all!",
  ui_story_5030_50300003_29_dialog_content = "Ahem! Go ahead, Merylt! Tell him the story!",
  ui_story_5030_50300003_30_dialog_content = "Uh... Oh...!",
  ui_story_5030_50300003_31_dialog_content = "Hey! You were fine around PlayerName just a second ago, so why are you suddenly clamming up now?!",
  ui_story_5030_50300003_32_dialog_content = "Shhh! Let her tell the story, would you?",
  ui_story_5030_50300003_33_dialog_content = "A-A long, long time ago...",
  ui_story_5030_50300003_34_dialog_content = "In a distant and hidden corner of Astra, there was once a brutal queen.",
  ui_story_5030_50300003_35_dialog_content = "The queen had ruled this place for decades, and her subjects had lived peaceful, self-sufficient lives under her reign.",
  ui_story_5030_50300003_36_dialog_content = "But when the queen turned sixty years old... The mask fell away, and their false peace along with it.",
  ui_story_5030_50300003_37_dialog_content = "How could this be?! No matter what I do, I cannot make these wrinkles go away!",
  ui_story_5030_50300003_38_dialog_content = "No... I cannot grow old like this...",
  ui_story_5030_50300003_39_dialog_content = "My people can only lead happy and peaceful lives under my rule!",
  ui_story_5030_50300003_40_dialog_content = "Tell me! What must I do to prolong my life and my reign over these lands?",
  ui_story_5030_50300003_41_dialog_content = "Oh!",
  ui_story_5030_50300003_42_dialog_content = "There is a way...",
  ui_story_5030_50300003_43_dialog_content = "A forbidden technique mentioned only in legends...",
  ui_story_5030_50300003_44_dialog_content = "By immersing oneself in the lifeblood of young boys and girls...",
  ui_story_5030_50300003_45_dialog_content = "And forgoing food in favor of their precious, youthful essence...",
  ui_story_5030_50300003_46_dialog_content = "From that day on, the lives of her subjects were forever changed.",
  ui_story_5030_50300003_47_dialog_content = "Children began to disappear before their very eyes, and chaos soon descended upon the land.",
  ui_story_5030_50300003_48_dialog_content = "Was there nothing that could stop the madness? Nothing at all?",
  ui_story_5030_50300003_49_dialog_content = "The answer soon began to ring out from deep within the hearts of every survivor in the kingdom...",
  ui_story_5030_50300003_50_dialog_content = "Resist! Revolt! Only by overthrowing the wicked queen would they finally know peace once more!",
  ui_story_5030_50300003_51_dialog_content = "...",
  ui_story_5030_50300003_52_dialog_content = "...",
  ui_story_5030_50300003_53_dialog_content = "And sure enough, the queen's tyranny was ultimately stopped by the people whom she desperately sought to continue ruling.",
  ui_story_5030_50300003_54_dialog_content = "In time, smiles reappeared on the faces of children, as peace and safety returned to the kingdom once again.",
  ui_story_5030_50300003_55_dialog_content = "But...",
  ui_story_5030_50300003_56_dialog_content = "Though the queen's ambitions for eternal life were steeped in violence and terror...",
  ui_story_5030_50300003_57_dialog_content = "Those with sharper minds can learn something valuable from her example...",
  ui_story_5030_50300003_58_dialog_content = "The art of extraction.",
  ui_story_5030_50300003_59_dialog_content = "From plants, we are able to extract their essence and create all manner of seasonings and ingredients.",
  ui_story_5030_50300003_60_dialog_content = "This is the gift that we offer you today.",
  ui_story_5030_50300003_61_dialog_content = "Incredible... Merylt was actually able to tell the entire story in front of PlayerName without missing a beat!",
  ui_story_5030_50300003_62_dialog_content = "This calls for a celebration!",
  ui_story_5030_50300003_63_dialog_content = "Here! Take a whiff!",
  ui_story_5030_50300003_64_dialog_content = "W-Wait a minute! Don't look at me like that! It's freaking me out!",
  ui_story_5030_50300003_65_dialog_content = "Don't get me wrong, I'm grateful for the gift, but I just have to make sure...",
  ui_story_5030_50300003_66_dialog_content = "Th-That story about the wicked queen and what she did to those children... It's not based on a real story, is it?",
  ui_story_5030_50300003_66X_dialog_content = "This story you're telling is too scary!",
  ui_story_5030_50300003_67_dialog_content = "Who can say? There's always some truth hidden in every legend, after all...",
  ui_story_5030_50300003_68_dialog_content = "Anyway, we brought you your gift, so hurry up and take it, okay?",
  ui_story_5030_50300003_69_dialog_content = "C-Could it be...",
  ui_story_5030_50300003_70_dialog_content = "Could it be that... you don't like our gift?",
  ui_story_5030_50300003_71_dialog_content = "Ah! N-No, I like it!",
  ui_story_5030_50300003_72_dialog_content = "I was just asking about the story, that's all!",
  ui_story_5030_50300003_73_dialog_content = "I mean, it was pretty scary, after all.",
  ui_story_5030_50300003_74_dialog_content = "You wanted me to smell it, right? Here goes...",
  ui_story_5030_50300003_75_dialog_content = "Wait, this smells amazing!",
  ui_story_5030_50300003_76_dialog_content = "Yeah, yeah!",
  ui_story_5030_50300003_77_dialog_content = "Although, I still have to ask... What kind of plant did you use to make this?",
  ui_story_5030_50300003_78_dialog_content = "I feel like I won't be able to use it properly unless I know exactly what it's made of.",
  ui_story_5030_50300003_79_dialog_content = "People will be eating it in my cooking, so I have to take this kind of thing seriously.",
  ui_story_5030_50300003_80_dialog_content = "Hehe!",
  ui_story_5030_50300003_81_dialog_content = "It took me almost a stinkin' day, but thankfully... It seems no animals were harmed in the making of that seasoning!",
  ui_story_5030_50300003_82_dialog_content = "Fia?",
  ui_story_5030_50300003_83_dialog_content = "You've been eavesdropping on us this entire time, haven't you?",
  ui_story_5030_50300003_84_dialog_content = "What? How could it be \"eavesdropping,\" when this is clearly a public space?",
  ui_story_5030_50300003_85_dialog_content = "I just came to try out all the tasty treats on sale. Is that so wrong?",
  ui_story_5030_50300003_86_dialog_content = "But in order to make sure that the seasoning they gave you is really plant-based, you'll have to...",
  ui_story_5030_50300003_87_dialog_content = "You'll have to let me sniff it, too!",
  ui_story_5030_50300003_88_dialog_content = "Hey, twerp! That's Merylt's gift to PlayerName, so keep your grubby mitts to yourself!",
  ui_story_5030_50300003_89_dialog_content = "*Sobbing* But... But...!",
  ui_story_5030_50300003_90_dialog_content = "(Is she really busting out the fake tears over this?!)",
  ui_story_5030_50300003_91_dialog_content = "I... I just wanted a little sniff, that's all... I would never steal it or anything...",
  ui_story_5030_50300003_92_dialog_content = "Urgh... Why, you irritating little brat!",
  ui_story_5030_50300003_93_dialog_content = "It's fine, Subli.",
  ui_story_5030_50300003_94_dialog_content = "Go ahead and smell it if you like, Fia.",
  ui_story_5030_50300003_95_dialog_content = "I can assure you, this was made using plants that I painstakingly gathered over a long period of time.",
  ui_story_5030_50300003_96_dialog_content = "See? Smells wonderful, doesn't it?",
  ui_story_5030_50300003_97_dialog_content = "Yeah, you're right!",
  ui_story_5030_50300003_98_dialog_content = "And it does have a kind of plant-like fragrance to it, as well...",
  ui_story_5030_50300003_99_dialog_content = "That settles it, PlayerName! This seasoning passes my professional assessment!",
  ui_story_5030_50300003_100_dialog_content = "I never asked for a \"professional assessment\"... You're the one who wouldn't let it go...",
  ui_story_5030_50300003_101_dialog_content = "I-I have no idea what you're talking about!",
  ui_story_5030_50300003_102_dialog_content = "Anyway, thank you, Merylt.",
  ui_story_5030_50300003_103_dialog_content = "D-Don't mention it...!",
  ui_story_5030_50300003_104_dialog_content = "Now let's see what this does to the flavor of my broth when I add it...",
  ui_story_5030_50300003_105_dialog_content = "Hey, what's that smell?",
  ui_story_5030_50300003_106_dialog_content = "It smells amazing!",
  ui_story_5030_50300003_107_dialog_content = "I think it's coming from over there! C'mon, let's take a look!",
  ui_story_5030_50300004_1_dialog_content = "Number 78! Your noodles are ready!",
  ui_story_5030_50300004_2_dialog_content = "Number 78! Number 78?",
  ui_story_5030_50300004_3_dialog_content = "Number 78, your order is—",
  ui_story_5030_50300004_4_dialog_content = "What's this mess? This place is utter chaos... I have no idea where the line begins or ends!",
  ui_story_5030_50300004_5_dialog_content = "S-Sorry about that! The end of the line is...",
  ui_story_5030_50300004_6_dialog_content = "Crap... I'm not so sure where it is, either!",
  ui_story_5030_50300004_7_dialog_content = "How about this? You tell me what you'd like, and I'll call your number when your order is ready.",
  ui_story_5030_50300004_8_dialog_content = "Well, how many orders are ahead of mine?",
  ui_story_5030_50300004_9_dialog_content = "Let me see...",
  ui_story_5030_50300004_10_dialog_content = "Well, you would be Number 103, so... T-Twenty orders, give or take.",
  ui_story_5030_50300004_11_dialog_content = "Hey! Did you get my order wrong or something?",
  ui_story_5030_50300004_12_dialog_content = "I clearly asked for soup noodle, but you served me noodles with meat sauce!",
  ui_story_5030_50300004_13_dialog_content = "M-My apologies! Let me make you another bowl...",
  ui_story_5030_50300004_14_dialog_content = "Hey! No cutting the line! We've been waiting here long enough, as it is!",
  ui_story_5030_50300004_15_dialog_content = "(Everything's a total mess right now... This is bad!)",
  ui_story_5030_50300004_16_dialog_content = "(Should I stop taking new orders? If I do, I can focus on the customers who are already waiting for their food.)",
  ui_story_5030_50300004_17_dialog_content = "Here's your noodle.",
  ui_story_5030_50300004_18_dialog_content = "Hmph. That's more like it.",
  ui_story_5030_50300004_19_dialog_content = "Your noodles will be ready just as soon as the kettle boils, as well.",
  ui_story_5030_50300004_20_dialog_content = "Sunstone! A little more, if you would?",
  ui_story_5030_50300004_21_dialog_content = "Your order is ready, as well. All it's missing are the toppings... There you go.",
  ui_story_5030_50300004_22_dialog_content = "Hehe! It always tastes best when it's fresh!",
  ui_story_5030_50300004_23_dialog_content = "Looks like that stall is putting out orders a little quicker now.",
  ui_story_5030_50300004_24_dialog_content = "Seems that way. The line's moving a lot faster, too!",
  ui_story_5030_50300004_25_dialog_content = "...",
  ui_story_5030_50300004_26_dialog_content = "L-Leona?!",
  ui_story_5030_50300004_27_dialog_content = "Why so surprised? Your eyes nearly popped out of your sockets, you know?",
  ui_story_5030_50300004_28_dialog_content = "S-Sorry, I just didn't know what to be surprised about first...",
  ui_story_5030_50300004_29_dialog_content = "Seeing you visit this place, or seeing you ask Sunstone to boil water with its flaming breath.",
  ui_story_5030_50300004_30_dialog_content = "It doesn't matter to me.",
  ui_story_5030_50300004_31_dialog_content = "I saw the queue for this stall was completely out of control, so I was curious to see what was on sale.",
  ui_story_5030_50300004_32_dialog_content = "I didn't expect to see you here, either.",
  ui_story_5030_50300004_33_dialog_content = "Or to see you fumbling and floundering around like this. I've never seen this side of you before.",
  ui_story_5030_50300004_34_dialog_content = "Uh... Hahaha...",
  ui_story_5030_50300004_35_dialog_content = "I was just a little overwhelmed by the sheer number of customers, that's all.",
  ui_story_5030_50300004_36_dialog_content = "I see... With Sunstone helping you boil water, your efficiency should increase considerably.",
  ui_story_5030_50300004_37_dialog_content = "Although... Is it just me, or is the crowd around the stall getting bigger and bigger?",
  ui_story_5030_50300004_38_dialog_content = "Hey, you there.",
  ui_story_5030_50300004_39_dialog_content = "The line is that way. What are you doing hanging around here?",
  ui_story_5030_50300004_40_dialog_content = "Uh, Leona? I think...",
  ui_story_5030_50300004_41_dialog_content = "I think they're here to watch Sunstone's \"fire-breathing act.\"",
  ui_story_5030_50300004_42_dialog_content = "What could be so interesting about Sunstone breathing fire? It's perfectly normal.",
  ui_story_5030_50300004_43_dialog_content = "U-Um...",
  ui_story_5030_50300004_44_dialog_content = "Maybe to you, but I'm guessing not everyone has had a chance to see a real dragon before.",
  ui_story_5030_50300004_45_dialog_content = "Alright.",
  ui_story_5030_50300004_46_dialog_content = "Look! A fire-breathing dragon!",
  ui_story_5030_50300004_47_dialog_content = "Have you ever seen one before?",
  ui_story_5030_50300004_48_dialog_content = "Nope! I've heard lots of stories about them, but this is my first time seeing a live one in person!",
  ui_story_5030_50300004_49_dialog_content = "It's so little and cute! It must be pretty young, huh?",
  ui_story_5030_50300004_50_dialog_content = "So you sell noodles here?",
  ui_story_5030_50300004_51_dialog_content = "Come on, let's get in line!",
  ui_story_5030_50300004_52_dialog_content = "There are even more people now...",
  ui_story_5030_50300004_53_dialog_content = "Looks like Sunstone really knows how to draw a crowd.",
  ui_story_5030_50300004_54_dialog_content = "Hmm...",
  ui_story_5030_50300004_55_dialog_content = "Leona? Could I ask for a favor?",
  ui_story_5030_50300004_56_dialog_content = "Ahem, if you don't have anything else to do today...",
  ui_story_5030_50300004_57_dialog_content = "Yes.",
  ui_story_5030_50300004_58_dialog_content = "Rest assured, I'll stay until it's a little less busy.",
  ui_story_5030_50300004_59_dialog_content = "Now now, don't be making those puppy dog eyes.",
  ui_story_5030_50300004_60_dialog_content = "Go take care of business.",
  ui_story_5030_50300004_61_dialog_content = "Right.",
  ui_story_5030_50300004_62_dialog_content = "Next customer, please!",
  ui_story_5030_50300004_63_dialog_content = "Which kind do you want?",
  ui_story_5030_50300005_1_dialog_content = "This is your bread. Here you are.",
  ui_story_5030_50300005_2_dialog_content = "Gee, that's a little hot straight from the oven...",
  ui_story_5030_50300005_3_dialog_content = "Let me wrap it up nicely for you.",
  ui_story_5030_50300005_4_dialog_content = "Huh? A customer wants my autograph? Of course!",
  ui_story_5030_50300005_5_dialog_content = "Where would you like me to sign?",
  ui_story_5030_50300005_6_dialog_content = "We want one too! Us too!",
  ui_story_5030_50300005_7_dialog_content = "That's not a problem, but could I ask everyone to be a little patient? There's a pretty long line!",
  ui_story_5030_50300005_8_dialog_content = "You want ten? I see...",
  ui_story_5030_50300005_9_dialog_content = "Dear guests, I'm sure you've grasped the true essence of shaved ice by now.",
  ui_story_5030_50300005_10_dialog_content = "Trying different flavors of shaved ice won't just broaden your gustative horizons, but also help build a healthy physique.",
  ui_story_5030_50300005_11_dialog_content = "Wow, it really is delicious...!",
  ui_story_5030_50300005_12_dialog_content = "Why does it say \"join us\" on your sign?",
  ui_story_5030_50300005_13_dialog_content = "Ever since I got into the shaved ice gig, the tills have never stopped ringing.",
  ui_story_5030_50300005_14_dialog_content = "Becoming a franchisee means you get to make as much money as I do.",
  ui_story_5030_50300005_15_dialog_content = "Learn the tricks of the trade, esteemed guests, and join the exciting world of shaved ice!",
  ui_story_5030_50300005_16_dialog_content = "Sounds pretty good... Shall we buy one first and have a taste?",
  ui_story_5030_50300005_17_dialog_content = "Yeah, let's try one.",
  ui_story_5030_50300005_18_dialog_content = "Here's yours.",
  ui_story_5030_50300005_19_dialog_content = "And here's yours!",
  ui_story_5030_50300005_20_dialog_content = "Be a rational consumer and reduce waste! Got it?",
  ui_story_5030_50300005_21_dialog_content = "Hand-grilled barbecue is really novel!",
  ui_story_5030_50300005_22_dialog_content = "Me! Give me one too, please!",
  ui_story_5030_50300005_23_dialog_content = "Well, business looks pretty good for everyone!",
  ui_story_5030_50300005_24_dialog_content = "Next up, this is Rainbow with some more details about the competition!",
  ui_story_5030_50300005_25_dialog_content = "The current top-ranked stall owner is—Mr. Fleur!",
  ui_story_5030_50300005_26_dialog_content = "Ha, that's not exactly a surprise. Just look at the line in front.",
  ui_story_5030_50300005_27_dialog_content = "Coming in second—Mr. Kleken!",
  ui_story_5030_50300005_28_dialog_content = "While shaved ice is undoubtedly tricky to store, his excellent marketing skills have netted him a great result.",
  ui_story_5030_50300005_29_dialog_content = "In third place—Ms. Smokey!",
  ui_story_5030_50300005_30_dialog_content = "While she may be a bit of a sourpuss, there's no denying that her business has been excellent!",
  ui_story_5030_50300005_31_dialog_content = "It seems like everyone went all-out, just to get their hands on this Sorcery Pot!",
  ui_story_5030_50300005_32_dialog_content = "Oops, almost forgot our PlayerName!",
  ui_story_5030_50300005_33_dialog_content = "Alright! Actually, PlayerName's result is pretty good too.",
  ui_story_5030_50300005_34_dialog_content = "While his result didn't dazzle as much as our top three, there's no doubt that with a bit of hard work, victory is possible!",
  ui_story_5030_50300005_35_dialog_content = "Uh... Hahaha...!",
  ui_story_5030_50300005_36_dialog_content = "Well, that's the end of the half-time broadcast!",
  ui_story_5030_50300005_37_dialog_content = "When next we meet, it'll be time to announce the results of the competition!",
  ui_story_5030_50300005_38_dialog_content = "To get that mysterious cooking utensil, and make your dreams come true!",
  ui_story_5030_50300005_39_dialog_content = "Come on, everyone!",
  ui_story_5030_50300005_40_dialog_content = "Step right up and get involved!",
  ui_story_5030_50300005_41_dialog_content = "Phew... I'm feeling the pressure.",
  ui_story_5030_50300005_42_dialog_content = "There are fewer customers too, since Leona left.",
  ui_story_5030_50300005_43_dialog_content = "Sure enough, they came all the way here to have noodles just to watch that fire-breathing dragon...",
  ui_story_5030_50300005_44_dialog_content = "This doesn't seem to work.",
  ui_story_5030_50300005_45_dialog_content = "You do look pretty worried right now.",
  ui_story_5030_50300005_46_dialog_content = "I'm curious, PlayerName, by what troubles are you trapped?",
  ui_story_5030_50300005_47_dialog_content = "Hi, Genevieve.",
  ui_story_5030_50300005_48_dialog_content = "Ah, did you come for the noodle?",
  ui_story_5030_50300005_49_dialog_content = "Uh, hold on. I've got it. You're looking for someone, right?",
  ui_story_5030_50300005_50_dialog_content = "Well, there she is...",
  ui_story_5030_50300005_51_dialog_content = "Hey, hold up! Wait a second!",
  ui_story_5030_50300005_52_dialog_content = "Whatever are you thinking, poor PlayerName?",
  ui_story_5030_50300005_53_dialog_content = "I'm only here to help you.",
  ui_story_5030_50300005_54_dialog_content = "Help me?",
  ui_story_5030_50300005_55_dialog_content = "Oh, I remember now. Aren't you also pretty skilled with fire...?",
  ui_story_5030_50300005_56_dialog_content = "Help you boil the water quicker, then rinse and repeat?",
  ui_story_5030_50300005_57_dialog_content = "Even so, that's just a repeat of recent results, not any huge improvement.",
  ui_story_5030_50300005_58_dialog_content = "You, you should look at the bigger picture.",
  ui_story_5030_50300005_59_dialog_content = "People come here for something fresh and new, right?",
  ui_story_5030_50300005_60_dialog_content = "Think about it.",
  ui_story_5030_50300005_61_dialog_content = "Imagine if your stall didn't just offer sustenance, but also provided some extras for tired customers?",
  ui_story_5030_50300005_62_dialog_content = "What do you mean by \"extras\"?",
  ui_story_5030_50300005_63_dialog_content = "U-Um, Genevieve, we're in Lumopolis turf. This isn't True Order or Umbraton territory.",
  ui_story_5030_50300005_64_dialog_content = "Won't we be arrested if we take it too far?",
  ui_story_5030_50300005_65_dialog_content = "About what?",
  ui_story_5030_50300005_66_dialog_content = "By \"extras,\" I mean better customer services like line-holding and massages!",
  ui_story_5030_50300005_67_dialog_content = "Oh, THOSE sorts of services!",
  ui_story_5030_50300005_68_dialog_content = "I thought you wanted me to throw in some gin or something!",
  ui_story_5030_50300005_69_dialog_content = "Let's wait until the evening for that sort of thing!",
  ui_story_5030_50300005_70_dialog_content = "It's too hot out there to drink now anyway, and impossible to savor gin's deliciousness.",
  ui_story_5030_50300005_71_dialog_content = "Alright, well, thanks for your suggestion, Genevieve...",
  ui_story_5030_50300005_72_dialog_content = "B-But, the thing is, I don't really have any spare hands to offer such services?",
  ui_story_5030_50300005_73_dialog_content = "Don't need your hands.",
  ui_story_5030_50300005_74_dialog_content = "I already have a lot \"lackeys\" lending hands...",
  ui_story_5030_50300005_75_dialog_content = "Lady Genevieve! Lady Genevieve!!",
  ui_story_5030_50300006_1_dialog_content = "(It must be really baking right now.)",
  ui_story_5030_50300006_2_dialog_content = "(I just felt sweat drip from my chin...)",
  ui_story_5030_50300006_3_dialog_content = "(If I listen carefully, I could probably hear that drop of sweat hit the ground.)",
  ui_story_5030_50300006_4_dialog_content = "(At least there's still a breeze, even on such a hot day...)",
  ui_story_5030_50300006_5_dialog_content = "(I can't feel the cool relief the wind brings... or even feel the wind itself.)",
  ui_story_5030_50300006_6_dialog_content = "(Eh... Then how do I know that it's even blowing?)",
  ui_story_5030_50300006_7_dialog_content = "(Well, must have been those three leaves fluttering in the air in front of me.)",
  ui_story_5030_50300006_8_dialog_content = "(Three leaves... Water stains on the ground. And a dish that someone accidentally broke... Eh?)",
  ui_story_5030_50300006_9_dialog_content = "(A pair of shoes appeared on the ground. The pointy toes of them stop in front of me...)",
  ui_story_5030_50300006_10_dialog_content = "Hold on... Pointy toes, stopping in front of my ramen stall?",
  ui_story_5030_50300006_11_dialog_content = "So, that means...",
  ui_story_5030_50300006_12_dialog_content = "A guest! A long-awaited GUEST!",
  ui_story_5030_50300006_13_dialog_content = "Dear guest, please, take a look! Check out our noodles!",
  ui_story_5030_50300006_14_dialog_content = "Business doesn't seem too brisk.",
  ui_story_5030_50300006_15_dialog_content = "Eh... Jeno?",
  ui_story_5030_50300006_16_dialog_content = "You're here for the noodles?",
  ui_story_5030_50300006_17_dialog_content = "Or are you doing the rounds as host...?",
  ui_story_5030_50300006_18_dialog_content = "I'm here for the noodles.",
  ui_story_5030_50300006_19_dialog_content = "... Oh! I see.",
  ui_story_5030_50300006_20_dialog_content = "And what sort of noodle are you after?",
  ui_story_5030_50300006_21_dialog_content = "There aren't many people here right now, so I could let you try them all...",
  ui_story_5030_50300006_22_dialog_content = "A bowl of soup noodle is fine.",
  ui_story_5030_50300006_23_dialog_content = "Thank you.",
  ui_story_5030_50300006_24_dialog_content = "Of course! Coming right up...",
  ui_story_5030_50300006_25_dialog_content = "So, what do you think? Is it good?",
  ui_story_5030_50300006_26_dialog_content = "Quite delicious.",
  ui_story_5030_50300006_27_dialog_content = "That's good to hear.",
  ui_story_5030_50300006_28_dialog_content = "So I can't understand why your business is so slow right now.",
  ui_story_5030_50300006_29_dialog_content = "Surely there should be more demand for this sort of thing, right?",
  ui_story_5030_50300006_30_dialog_content = "To be honest, business wasn't so bad just now...",
  ui_story_5030_50300006_31_dialog_content = "It's just that the guests seemed more attracted by extras.",
  ui_story_5030_50300006_32_dialog_content = "Extras?",
  ui_story_5030_50300006_33_dialog_content = "Hmm... Maybe better to say gimmicks to drum up business.",
  ui_story_5030_50300006_34_dialog_content = "Like the fire-breathing dragon or better customer services. Things like that.",
  ui_story_5030_50300006_35_dialog_content = "Well, does the noodle taste any different?",
  ui_story_5030_50300006_36_dialog_content = "Much the same, I guess. Your ramen and those sold earlier were both made in exactly the same way.",
  ui_story_5030_50300006_37_dialog_content = "You must have had loads of customers, right?",
  ui_story_5030_50300006_38_dialog_content = "Yep. There was definitely a long line.",
  ui_story_5030_50300006_39_dialog_content = "You must be anxious about serving up noodles to each customer even quicker back then, I suppose.",
  ui_story_5030_50300006_40_dialog_content = "Well, that's true...",
  ui_story_5030_50300006_41_dialog_content = "Hmm... I think I understand what you're trying to say.",
  ui_story_5030_50300006_42_dialog_content = "Because I was in such a hurry, it was hard to avoid mistakes.",
  ui_story_5030_50300006_43_dialog_content = "And because of that, there's no chance of making those servings to the same standard as what you just had.",
  ui_story_5030_50300006_44_dialog_content = "No... I mean, I think you should focus more on the food itself.",
  ui_story_5030_50300006_45_dialog_content = "The stress dealing with long lines is just one issue.",
  ui_story_5030_50300006_46_dialog_content = "But the bottom line is that you just can't manage to serve that many people.",
  ui_story_5030_50300006_47_dialog_content = "Perhaps. But they don't have the patience to wait for long.",
  ui_story_5030_50300006_48_dialog_content = "How about warning them of the approximate wait time?",
  ui_story_5030_50300006_49_dialog_content = "The customers attracted by the extras would be even more impatient.",
  ui_story_5030_50300006_50_dialog_content = "I think it's a paradox...",
  ui_story_5030_50300006_51_dialog_content = "You see, the whole point is that I want to get my hands on that pot. And for that to happen, the more sales the better.",
  ui_story_5030_50300006_52_dialog_content = "So you think extras are just something you have to do.",
  ui_story_5030_50300006_53_dialog_content = "But can you guarantee that all the people attracted by the extras actually buy your noodles?",
  ui_story_5030_50300006_54_dialog_content = "...",
  ui_story_5030_50300006_55_dialog_content = "Well, I... No.",
  ui_story_5030_50300006_56_dialog_content = "It's just that I get even more flustered when I see so many people waiting.",
  ui_story_5030_50300006_57_dialog_content = "And a little anxious.",
  ui_story_5030_50300006_58_dialog_content = "All I can think about is getting one bowl done, and then the next, and the one after that...",
  ui_story_5030_50300006_59_dialog_content = "I really mean it when I said this bowl of noodle before me was delicious.",
  ui_story_5030_50300006_60_dialog_content = "I daren't say, \"cool heads produce hot noodles.\"",
  ui_story_5030_50300006_61_dialog_content = "Or \"Focus on food, forget the world,\" such trite slogans.",
  ui_story_5030_50300006_62_dialog_content = "Well, all I want to say is: This bowl of noodle is quite delicious.",
  ui_story_5030_50300006_63_dialog_content = "If I know someone intends to open a restaurant in the future, I'll point them in your direction for tips about making noodles.",
  ui_story_5030_50300006_64_dialog_content = "Hmm...",
  ui_story_5030_50300006_65_dialog_content = "Thank you, Jeno.",
  ui_story_5030_50300006_66_dialog_content = "Is this what you thought when you first started performing?",
  ui_story_5030_50300006_67_dialog_content = "You know, pay no attention to the size of the audience but just focus on the magic?",
  ui_story_5030_50300006_68_dialog_content = "Yes.",
  ui_story_5030_50300006_69_dialog_content = "Magic is my life. I don't care about anything else.",
  ui_story_5030_50300006_70_dialog_content = "I've gotta say, that kind of attitude rocks.",
  ui_story_5030_50300006_71_dialog_content = "You've got a few more guests.",
  ui_story_5030_50300006_72_dialog_content = "If you'll excuse me. I look forward to your miracles.",
  ui_story_5030_50300006_73_dialog_content = "Focus on the food itself...?",
  ui_story_5030_50300006_74_dialog_content = "The noodles were great. Take these ingredients as a thank you!",
  ui_story_5030_50300006_75_dialog_content = "I can assure you, this was made using plants that I painstakingly gathered over a long period of time.",
  ui_story_5030_50300006_76_dialog_content = "See? Smells wonderful, doesn't it?",
  ui_story_5030_50300006_77_dialog_content = "This secret cookbook is for you!",
  ui_story_5030_50300006_78_dialog_content = "You certainly won't let us down, will you, PlayerName?",
  ui_story_5030_50300006_79_dialog_content = "Ah! I get it!",
  ui_story_5030_50300007_1_dialog_content = "Did you hear? That absolute legend is also going to be taking part!",
  ui_story_5030_50300007_2_dialog_content = "Uncle Johnny? You mean Uncle Johnny is coming here, in person?!",
  ui_story_5030_50300007_3_dialog_content = "No, no... I think his name was something like Noodle God.",
  ui_story_5030_50300007_4_dialog_content = "My friend went to try out Noodle God's stall. Verdict: he's never had such delicious noodle in his entire life!",
  ui_story_5030_50300007_5_dialog_content = "Really? That does sound divine. I think I want to try some, too.",
  ui_story_5030_50300007_6_dialog_content = "See, just over there—",
  ui_story_5030_50300007_7_dialog_content = "203! That's me! Order number 203!",
  ui_story_5030_50300007_8_dialog_content = "You've been fooled, buddy. I think you'll find that I'm 203.",
  ui_story_5030_50300007_9_dialog_content = "Seeing as the 203s are fighting it out, why not just give it to me? I'm 204!",
  ui_story_5030_50300007_10_dialog_content = "Wow... Too many people in line...?",
  ui_story_5030_50300007_11_dialog_content = "(My arms ache...)",
  ui_story_5030_50300007_12_dialog_content = "(I'm not even sure I can do something as basic as handing over the bowls...)",
  ui_story_5030_50300007_13_dialog_content = "(But if it wasn't for that...)",
  ui_story_5030_50300007_14_dialog_content = "(For my ultimate dream!)",
  ui_story_5030_50300007_15_dialog_content = "(To enable everyone in Cloud Gardens and Colossus to enjoy delicious, convenient noodles!)",
  ui_story_5030_50300007_16_dialog_content = "—Hey! 204! You're up!",
  ui_story_5030_50300007_17_dialog_content = "Wow! Seems like it's buzzing around here, PlayerName!",
  ui_story_5030_50300007_18_dialog_content = "Uh, you're here for the noodles too, Rainbow?",
  ui_story_5030_50300007_19_dialog_content = "Not this time. I'm here to make a competition announcement!",
  ui_story_5030_50300007_20_dialog_content = "CONGRATULATIONS, PlayerName!",
  ui_story_5030_50300007_21_dialog_content = "Con-congratulating me?",
  ui_story_5030_50300007_22_dialog_content = "Are you telling me that I made it—",
  ui_story_5030_50300007_23_dialog_content = "You are now in second place!",
  ui_story_5030_50300007_24_dialog_content = "... What exactly are you congratulating me for then?",
  ui_story_5030_50300007_25_dialog_content = "Huh? You were fourth at the end of the last round!",
  ui_story_5030_50300007_26_dialog_content = "That's some congratulation-worthy progress if ever there was some!",
  ui_story_5030_50300007_27_dialog_content = "Well, if you insist on putting it like that...",
  ui_story_5030_50300007_28_dialog_content = "Who's in first place?",
  ui_story_5030_50300007_29_dialog_content = "Only the founder of the bread empire—Mr. Fleur!",
  ui_story_5030_50300007_30_dialog_content = "We're down to the last half hour of the competition. Can hard work help PlayerName get over the line?",
  ui_story_5030_50300007_31_dialog_content = "I'm certainly gonna try.",
  ui_story_5030_50300007_32_dialog_content = "Is it ready? Am I up yet? I'm 205!",
  ui_story_5030_50300007_33_dialog_content = "One sec, almost done!",
  ui_story_5030_50300007_34_dialog_content = "Incredible! Even though he was chatting to the host, his hands never stopped!",
  ui_story_5030_50300007_35_dialog_content = "Is this the secret talent of the Noodle God?",
  ui_story_5030_50300007_36_dialog_content = "Noodle God?",
  ui_story_5030_50300007_37_dialog_content = "Why, hello there!",
  ui_story_5030_50300007_38_dialog_content = "Can I ask who you meant by \"Noodle God\"?",
  ui_story_5030_50300007_39_dialog_content = "Uh, just this noodle stall owner.",
  ui_story_5030_50300007_40_dialog_content = "Wow—now THAT'S a long line!",
  ui_story_5030_50300007_41_dialog_content = "It's only 'cuz his noodle is so tasty.",
  ui_story_5030_50300007_42_dialog_content = "Noodle God? Pff...",
  ui_story_5030_50300007_43_dialog_content = "Clearly only Anzu and Momo are worthy of such an epithet!",
  ui_story_5030_50300007_44_dialog_content = "I think I'd better take a closer look at this guy, see just how skilled he is!",
  ui_story_5030_50300007_45_dialog_content = "Next! Hi there! What flavor would you like—",
  ui_story_5030_50300007_46_dialog_content = "... Yao?!",
  ui_story_5030_50300007_47_dialog_content = "Whoa now! Gosh...!",
  ui_story_5030_50300007_48_dialog_content = "Hang on a minute... Are you telling me YOU'RE the Noodle God they were talking about?",
  ui_story_5030_50300007_49_dialog_content = "Well, listen, I might be the one that everyone's calling that but, but... It's not like I promoted myself that way!",
  ui_story_5030_50300007_50_dialog_content = "So it really is your cooking which has impressed everyone?",
  ui_story_5030_50300007_51_dialog_content = "I mean, yeah? Probably...",
  ui_story_5030_50300007_52_dialog_content = "Was coming here part of your travels?",
  ui_story_5030_50300007_53_dialog_content = "Yep! I wanted to have a look around!",
  ui_story_5030_50300007_54_dialog_content = "But I gotta say it's a bit of a strange sight—you, by yourself, cooking noodles!",
  ui_story_5030_50300007_55_dialog_content = "Ohhh! So it's for that Sorcery Pot, eh? No wonder I just saw Kleken over there...",
  ui_story_5030_50300007_56_dialog_content = "Wow, what an unexpectedly noble motivation to win, PlayerName!",
  ui_story_5030_50300007_57_dialog_content = "Woo... Boo-hoo... I feel you. Say no more, PlayerName!",
  ui_story_5030_50300007_58_dialog_content = "There's gotta be at least 20 people behind me. How many more orders can you make?",
  ui_story_5030_50300007_59_dialog_content = "Hmm... could you manage 87?",
  ui_story_5030_50300007_60_dialog_content = "Rest assured, these 87 bowls—",
  ui_story_5030_50300007_61_dialog_content = "ARE ALL NOW CONTRACTED BY ME!",
  ui_story_5030_50300007_62_dialog_content = "Who's the supplier of the noodles and the toppings?",
  ui_story_5030_50300007_63_dialog_content = "Let me buy up all the raw ingredients too!",
  ui_story_5030_50300007_64_dialog_content = "Yao, listen, I...",
  ui_story_5030_50300007_65_dialog_content = "Ehh, no need to thank me!",
  ui_story_5030_50300007_66_dialog_content = "For such a grand dream... I simply must lend a hand!",
  ui_story_5030_50300007_67_dialog_content = "Plus I'm phenomenally rich, haha!",
  ui_story_5030_50300007_68_dialog_content = "The final countdown begins—!",
  ui_story_5030_50300007_69_dialog_content = "Wow, every contestant is stepping up!",
  ui_story_5030_50300007_70_dialog_content = "At this incredibly tense moment—THREE!",
  ui_story_5030_50300007_71_dialog_content = "Kleken's written contact details for investment on his own tentacle!",
  ui_story_5030_50300007_72_dialog_content = "This is a nail-biting wait for the results—TWO!",
  ui_story_5030_50300007_73_dialog_content = "Fleur has once again flashed that trademark winning smile to his fans!",
  ui_story_5030_50300007_74_dialog_content = "The excitement is almost too much to handle—ONE!",
  ui_story_5030_50300007_75_dialog_content = "I hereby declare the champion of this battle for the Sorcery Pot to be—",
  ui_story_5030_50300007_76_dialog_content = "PlayerName!",
  ui_story_5030_50300007_77_dialog_content = "PlayerName, who sold an awesome amount of noodles, all in pursuit of his grand dream!",
  ui_story_5030_50300007_78_dialog_content = "Let us congratulate PlayerName on winning this mysterious and intriguing Sorcery Pot!",
  ui_story_5030_50300007_79_dialog_content = "Congratulations, PlayerName.",
  ui_story_5030_50300007_80_dialog_content = "So PlayerName won!",
  ui_story_5030_50300007_81_dialog_content = "Do you know how to use it?",
  ui_story_5030_50300007_82_dialog_content = "Err... Thanks, everyone.",
  ui_story_5030_50300007_83_dialog_content = "I reckon I need to spend time exploring how to use it.",
  ui_story_5030_50300007_84_dialog_content = "I do think I've seen this sort of cooking utensil before, but this pot...",
  ui_story_5030_50300007_85_dialog_content = "Uh, you don't know how to use it, do you?",
  ui_story_5030_50300007_86_dialog_content = "I, I just need to refresh my memory!",
  ui_story_5030_50300007_87_dialog_content = "(How exactly do I turn on auto-cook?)",
  ui_story_5030_50300007_88_dialog_content = "(Would I look a little stupid if I tried to sense it?)",
  ui_story_5030_50300007_89_dialog_content = "Can I have a look?",
  ui_story_5030_50300007_90_dialog_content = "Of course.",
  ui_story_5030_50300007_91_dialog_content = "I have no idea. This is totally different to any other cooking utensil I've ever seen...",
  ui_story_5030_50300007_92_dialog_content = "Um... But its exquisite structure really does make one wish to know how it works.",
  ui_story_5030_50300007_93_dialog_content = "PlayerName, when you've achieved your dream, could I possibly borrow this cooking utensil for a couple days?",
  ui_story_5030_50300007_94_dialog_content = "No problem! I just have to work out how the thing works, first...",
  ui_story_5030_50300007_95_dialog_content = "I reckon it needs some kind of external nudge to get going.",
  ui_story_5030_50300007_96_dialog_content = "Fire? Does it need fire?",
  ui_story_5030_50300007_97_dialog_content = "Can't hurt to try?",
  ui_story_5030_50300007_98_dialog_content = "... That goes too far, doesn't it?!",
  ui_story_5030_50300007_99_dialog_content = "But look, there's no damage.",
  ui_story_5030_50300007_100_dialog_content = "How about... trying some water?",
  ui_story_5030_50300007_101_dialog_content = "...",
  ui_story_5030_50300007_102_dialog_content = "Burn with ocean waves!",
  ui_story_5030_50300007_103_dialog_content = "It stays still.",
  ui_story_5030_50300007_104_dialog_content = "Er, maybe it needs some softer, more controlled kind of force?",
  ui_story_5030_50300007_105_dialog_content = "I'm here!",
  ui_story_5030_50300007_106_dialog_content = "It seems hard as a rock.",
  ui_story_5030_50300007_107_dialog_content = "Ce-ce...",
  ui_story_5030_50300007_108_dialog_content = "You can't use modern thinking to understand these sorts of ancient things from the ruins...",
  ui_story_5030_50300007_109_dialog_content = "But how will we ever know if we don't try?",
  ui_story_5030_50300007_110_dialog_content = "Well... Try attacking with Lumina?",
  ui_story_5030_50300007_111_dialog_content = "I, I...",
  ui_story_5030_50300007_112_dialog_content = "Sure enough, no dice...",
  ui_story_5030_50300007_113_dialog_content = "Did Uncle Johnny really once use this pot?",
  ui_story_5030_50300007_114_dialog_content = "I don't think these kind of legendary contraptions are very reliable!",
  ui_story_5030_50300007_115_dialog_content = "This \"auto-cook\" function... It's not like my moniker just now, is it? Just some kind of outrageous rhetorical exaggeration?",
  ui_story_5030_50300007_116_dialog_content = "Ha... Hahaha!",
  ui_story_5030_50300007_117_dialog_content = "Uh, this... I'm just paid to read the script!",
  ui_story_5030_50300007_118_dialog_content = "My point is, maybe it doesn't even have this function!",
  ui_story_5030_50300007_119_dialog_content = "I feel sorry for you, adorable warrior.",
  ui_story_5030_50300007_120_dialog_content = "I-if you don't mind, PlayerName, I-I could...",
  ui_story_5030_50300007_121_dialog_content = "I could take it back to Gannon City. See if Officer Gronru and her lot could work it out...",
  ui_story_5030_50300007_122_dialog_content = "Th-They know rather a lot about relics found in ruins...",
  ui_story_5030_50300007_123_dialog_content = "Doesn't seem like we have much choice right now.",
  ui_story_5030_50300007_124_dialog_content = "And so PlayerName comes to the end of his noodle journey.",
  ui_story_5030_50300007_125_dialog_content = "He claims that, although his reward has been taken away for studying, he found the whole experience interesting.",
  ui_story_5030_50300007_126_dialog_content = "After all, he has mastered the skill of cooking with heart, leading to great reviews from customers.",
  ui_story_5030_50300007_127_dialog_content = "And vile Kleken has again stolen plenty of good ideas about shaved ice optimization.",
  ui_story_5030_50300007_128_dialog_content = "Some people even really want to join his shaved ice business!",
  ui_story_5030_50300007_129_dialog_content = "Why, it was evidently my... Forget it. We'll see who's laughing later!",
  ui_story_5030_50300007_130_dialog_content = "Fleur's bread sold well, and his fans were ecstatic as always.",
  ui_story_5030_50300007_131_dialog_content = "Everyone is happy, except...",
  ui_story_5030_50300007_132_dialog_content = "Do you have any idea where that person is?",
  ui_story_5030_50300007_133_dialog_content = "Lady Genevieve! Are you still looking for that woman?",
  ui_story_5030_50300007_134_dialog_content = "I think she's already gone. Not here, at any rate.",
  ui_story_5030_50300007_135_dialog_content = "Hahaha! I knew it!",
  ui_story_5030_50300007_136_dialog_content = "Bet she's crawled back to some obscure corner to lick her wounds.",
  ui_story_5030_50300007_137_dialog_content = "Tsk, Smokey. One of those days for you, too?",
  ui_story_5030_50300007_138_dialog_content = "Hey, you, did no one ever teach you to whisper when slandering others?",
  ui_story_5030_50300007_139_dialog_content = "...?",
  ui_story_5030_50300007_140_dialog_content = "Isn't this Smokey of the Failed Dreams?",
  ui_story_5030_50300007_141_dialog_content = "How are you feeling? Unpleasant, no?",
  ui_story_5030_50300007_142_dialog_content = "Meh. I don't really care if I got the pot or not.",
  ui_story_5030_50300007_143_dialog_content = "I just want to find a nice place to set fires heartily.",
  ui_story_5030_50300007_144_dialog_content = "And yet the loser tries to be tough and brave! How amusing!",
  ui_story_5030_50300007_145_dialog_content = "What about you?",
  ui_story_5030_50300007_146_dialog_content = "Had to rack your brains to think of a way to make me lose, then smugly think I actually care?",
  ui_story_5030_50300007_147_dialog_content = "Are you sure you're just slightly obsessed with me, Genevieve?",
  ui_story_5030_50300007_148_dialog_content = "You? Who would waste their time? Who do you think you are?",
  ui_story_5030_50300007_149_dialog_content = "If you ask me, it's even lamer to be so idle every day that all you can do is run around chasing others.",
  ui_story_5030_50300007_150_dialog_content = "Isn't that right, little doggie?",
  ui_story_5030_50300007_151_dialog_content = "WHY YOU...!",
  ui_story_5030_50300007_152_dialog_content = "Bye for now, doggie. I'll be sure to come play fetch with you next time.",
  ui_story_5030_50300007_153_dialog_content = "...",
  ui_story_5030_50300007_154_dialog_content = "Oh! Lady Genevieve! Lady Genevieve!!",
  ui_story_5030_50300007_155_dialog_content = "Wake up! Come on! Q-Quickly, call a doctor—"
}
return config
